constraints:
1 ≤ S ≤ 10^{5}
1 ≤ D ≤ 10^{5}

expected time complexity: O(D)
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def secondSmallest(self, S, D):
		if S <= 9 and D == 1:
			return S
		if S >= 9 * D:
			return -1
		ret = []
		while S:
			if S >= 9:
				ret.append(9)
				S -= 9
			else:
				ret.append(S)
				S = 0
		if len(ret) < D:
			ret[-1] -= 1
			while len(ret) < D:
				ret.append(0)
			ret[-1] += 1
		for i in range(D):
			if ret[i] != 9:
				if i >= 1:
					ret[i] += 1
					ret[i - 1] -= 1
				else:
					ret[i] -= 1
					ret[i + 1] += 1
				break
		return int(''.join(map(str, ret[::-1])))
